import { truthy } from '../truthy';
export const getMetadataFromRiff = (structure) => {
    const boxes = structure.boxes.find((b) => b.type === 'list-box' && b.listType === 'INFO');
    if (!boxes) {
        return [];
    }
    const { children } = boxes;
    return children
        .map((child) => {
        if (child.type !== 'isft-box') {
            return null;
        }
        return {
            trackId: null,
            key: 'encoder',
            value: child.software,
        };
    })
        .filter(truthy);
};
